import { test, expect } from '@playwright/test';

test.describe('Field Validation Error States', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should display specific validation error for each invalid field', async ({ page }) => {
    // Fill in valid data
    await page.getByLabel('Full Name').fill('John Doe');
    await page.getByLabel('Email Address').fill('john@example.com');
    await page.getByLabel('Phone Number').fill('123456777');

    // Clear all fields
    await page.getByLabel('Full Name').clear();
    await page.getByLabel('Email Address').clear();
    await page.getByLabel('Phone Number').clear();

    // Submit with all fields empty
    await page.getByRole('button', { name: /submit/i }).click();

    // Verify validation errors are displayed for all fields
    const fullNameError = page.getByText('Full Name is required');
    await expect(fullNameError).toBeVisible();

    const emailError = page.getByText('Email Address is required');
    await expect(emailError).toBeVisible();

    const phoneError = page.getByText('Phone Number is required');
    await expect(phoneError).toBeVisible();

    // Verify error messages are associated with the correct fields
    await expect(fullNameError).toBeCloseTo(page.getByLabel('Full Name'));
    await expect(emailError).toBeCloseTo(page.getByLabel('Email Address'));
    await expect(phoneError).toBeCloseTo(page.getByLabel('Phone Number'));

    // Verify submit button is disabled
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeDisabled();
  });

  test('should display specific validation error for each invalid field when submitting with invalid data', async ({ page }) => {
    // Fill in invalid data
    await page.getByLabel('Full Name').fill('John Doe');
    await page.getByLabel('Email Address').fill('invalid-email');
    await page.getByLabel('Phone Number').fill('not a phone number');

    // Submit the form
    await page.getByRole('button', { name: /submit/i }).click();

    // Verify specific validation errors are displayed
    const fullNameError = page.getByText('Full Name is required');
    await expect(fullNameError).not.toBeVisible();

    const emailError = page.getByText('Please enter a valid email address');
    await expect(emailError).toBeVisible();

    const phoneError = page.getByText('Please enter a valid phone number');
    await expect(phoneError).toBeVisible();

    // Verify submit button remains disabled
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeDisabled();

    // Verify error messages are associated with the correct fields
    await expect(emailError).toBeCloseTo(page.getByLabel('Email Address'));
    await expect(phoneError).toBeCloseTo(page.getByLabel('Phone Number'));

    // Verify form does not submit
    const form = page.locator('[data-testid="form"]');
    await expect(form).toBeVisible();
  });
});
